-- ================================================================
-- HeroBook - Migration 006 : adaptation PDF fidèle - Les Maîtres des Ténèbres
-- ---------------------------------------------------------------
-- Cette migration est générée à partir du PDF fourni par l utilisateur.
-- Elle conserve les 350 sections, les renvois, le rulebook et les
-- caractéristiques de combat pour le mode de test HeroBook.
-- ================================================================

ALTER TABLE public.story_nodes ADD COLUMN IF NOT EXISTS metadata JSONB NOT NULL DEFAULT '{}'::jsonb;

CREATE TABLE IF NOT EXISTS public.story_rulebooks (
  story_id       UUID PRIMARY KEY REFERENCES public.stories(id) ON DELETE CASCADE,
  title          TEXT NOT NULL,
  content        TEXT NOT NULL,
  rule_data      JSONB NOT NULL DEFAULT '{}'::jsonb,
  source_credit  TEXT,
  source_path    TEXT,
  created_at     TIMESTAMPTZ DEFAULT NOW()
);
ALTER TABLE public.story_rulebooks ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "story_rulebooks_access_control" ON public.story_rulebooks;
CREATE POLICY "story_rulebooks_access_control" ON public.story_rulebooks FOR SELECT USING (
  EXISTS (
    SELECT 1 FROM public.stories s
    WHERE s.id = story_id AND s.status = 'published'
      AND (s.is_free = TRUE OR EXISTS (
        SELECT 1 FROM public.user_story_progress usp
        WHERE usp.story_id = s.id AND usp.user_id = auth.uid() AND usp.is_purchased = TRUE
      ))
  )
);
GRANT SELECT ON public.story_rulebooks TO anon, authenticated, service_role;

-- Les objets de l aventure sont accordés par le livre, pas vendus par la boutique.
DROP POLICY IF EXISTS "items_public_read" ON public.items;
CREATE POLICY "items_public_read" ON public.items FOR SELECT USING (
  is_available = TRUE OR EXISTS (
    SELECT 1 FROM public.user_inventory ui
    WHERE ui.user_id = auth.uid() AND ui.item_id = items.id AND ui.quantity > 0
  )
);

INSERT INTO public.stories (
  slug, title, tagline, description, author_note, genre, status, is_free,
  price_gems, price_usd, estimated_playtime_min, min_age, difficulty, tags, published_at
) VALUES (
  'les-maitres-des-tenebres', 'Les Maîtres des Ténèbres',
  'Loup Solitaire : le dernier Seigneur Kaï doit avertir le Roi.',
  'Version de test fidèle aux règles, aux 350 sections et aux renvois de l édition fournie. Choisissez vos Disciplines Kaï, gérez votre Feuille d Aventure et atteignez le Palais du Roi.',
  'Joe Dever, Les Maîtres des Ténèbres. Illustrations : Gary Chalk. Traduction française : Camille Fabien. Intégration HeroBook réalisée à partir du PDF fourni et autorisée par l utilisateur.',
  'adventure', 'published', TRUE, NULL, NULL, 180, 12, 4,
  ARRAY['loup-solitaire', 'livre-jeu', 'kai', 'sommerlund', 'holmgard', 'combat', 'regles'], NOW()
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title, tagline = EXCLUDED.tagline, description = EXCLUDED.description,
  author_note = EXCLUDED.author_note, genre = EXCLUDED.genre, status = EXCLUDED.status,
  is_free = TRUE, price_gems = NULL, price_usd = NULL, estimated_playtime_min = EXCLUDED.estimated_playtime_min,
  min_age = EXCLUDED.min_age, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, published_at = EXCLUDED.published_at;

